  const bounds = svg.getBoundingClientRect();
  const groups = [...svg.querySelectorAll('g')];
  return groups.map(g => {
    for (let y = 0.3; y <= 0.7; y += 0.05) {
      for (let x = 0.3; x <= 0.7; x += 0.05) {
        const point = { x: bounds.x + bounds.width * x, y: bounds.y + bounds.height * y };
        if (g.contains(document.elementFromPoint(point.x, point.y))) return { ...point, label: g.getAttribute('aria-label') };
